  'use strict';
  const DATA = __CELL5_FINAL_DATA__;
  const mapObj = window['__MAP_VAR__'] || null;
  if (!mapObj) return;

  const layerItems = Array.isArray(DATA.layerItems) ? DATA.layerItems : [];
  const inspectionRecords = DATA.inspectionRecords || {};
  const inspectionMeta = DATA.inspectionMeta || {};
  const dailyDayTargets = Array.isArray(DATA.dailyDayTargets) ? DATA.dailyDayTargets : [];
  const allInOneStartTarget = DATA.allInOneStartTarget || {};
  const sharedStartMarkerVar = String(DATA.sharedStartMarkerVar || '');
  const startDisplayName = String(DATA.startDisplayName || '固定起點');
  const startLat = Number(DATA.startLat);
  const startLon = Number(DATA.startLon);

  // ============================================================
  // v33.19：手機勘查點資訊防止水平溢出；長內容自動換行，操作按鈕必要時改為上下排列
  //   ．地圖中心位置
  //   ．地圖縮放程度
  //   ．「地圖顯示內容」中的圖層選擇狀態
  //   ．桌面版與手機直開版各自記住，不互相干擾
  //
  // 使用 localStorage；若瀏覽器或 file:// 不允許 storage，
  // 僅停用「記憶視圖」，不影響地圖其他功能。
  // ============================================================
  const CELL5_VIEW_STATE_VERSION = 'v33.18';
  const CELL5_VIEW_MODE = String(DATA.vehicleMode || 'CAR').toUpperCase();
  const CELL5_VIEW_VARIANT = /手機直開/.test(String(window.location && window.location.pathname || '')) ? 'mobile' : 'web';
  const CELL5_VIEW_STORAGE_KEY = 'cell5_view_state_' + CELL5_VIEW_STATE_VERSION + '_' + CELL5_VIEW_MODE + '_' + CELL5_VIEW_VARIANT;
  let cell5RestoringViewState = false;
  let cell5SaveTimer = null;

  function cell5ReadViewState(){
    try{
      if(!window.localStorage)return null;
      const raw=window.localStorage.getItem(CELL5_VIEW_STORAGE_KEY);
      if(!raw)return null;
      const state=JSON.parse(raw);
      return state && typeof state==='object' ? state : null;
    }catch(e){ return null; }
  }

  function cell5CurrentLayerState(){
    const states={};
    try{
      layerItems.forEach(function(item){
        if(!item||!item.var)return;
        const layer=window[item.var];
        states[String(item.var)]=!!(layer&&mapObj.hasLayer(layer));
      });
    }catch(e){}
    return states;
  }

  function cell5SaveViewState(){
    if(cell5RestoringViewState)return;
    try{
      if(!window.localStorage)return;
      const c=mapObj.getCenter ? mapObj.getCenter() : null;
      const state={
        version:CELL5_VIEW_STATE_VERSION,
        vehicleMode:CELL5_VIEW_MODE,
        variant:CELL5_VIEW_VARIANT,
        savedAt:new Date().toISOString(),
        center:c?{lat:Number(c.lat),lng:Number(c.lng)}:null,
        zoom:Number(mapObj.getZoom ? mapObj.getZoom() : NaN),
        layers:cell5CurrentLayerState()
      };
      window.localStorage.setItem(CELL5_VIEW_STORAGE_KEY,JSON.stringify(state));
    }catch(e){}
  }

  function cell5ScheduleSaveViewState(){
    if(cell5RestoringViewState)return;
    try{clearTimeout(cell5SaveTimer);}catch(e){}
    cell5SaveTimer=setTimeout(function(){
      cell5SaveTimer=null;
      cell5SaveViewState();
    },120);
  }

  function cell5RestoreViewState(){
    const state=cell5ReadViewState();
    if(!state)return false;
    cell5RestoringViewState=true;
    try{
      const savedLayers=state.layers&&typeof state.layers==='object'?state.layers:{};
      const savedBase=[];

      layerItems.forEach(function(item){
        if(!item||!item.var)return;
        const layer=window[item.var];
        if(!layer)return;
        const saved=savedLayers[String(item.var)];
        if(item.type==='base'){
          if(saved===true)savedBase.push(layer);
          return;
        }
        if(saved===true){
          try{if(!mapObj.hasLayer(layer))mapObj.addLayer(layer);}catch(e){}
        }else if(saved===false){
          try{if(mapObj.hasLayer(layer))mapObj.removeLayer(layer);}catch(e){}
        }
      });

      if(savedBase.length){
        layerItems.filter(function(item){return item&&item.type==='base';}).forEach(function(item){
          const base=window[item.var];
          if(base&&mapObj.hasLayer(base)&&savedBase.indexOf(base)===-1){
            try{mapObj.removeLayer(base);}catch(e){}
          }
        });
        try{if(!mapObj.hasLayer(savedBase[0]))mapObj.addLayer(savedBase[0]);}catch(e){}
      }

      const lat=Number(state.center&&state.center.lat);
      const lng=Number(state.center&&state.center.lng);
      const zoom=Number(state.zoom);
      if(Number.isFinite(lat)&&Number.isFinite(lng)&&Number.isFinite(zoom)){
        try{mapObj.setView([lat,lng],zoom,{animate:false});}catch(e){}
      }

      try{if(typeof syncLayerChecks==='function')syncLayerChecks();}catch(e){}
      try{if(typeof syncCustomLayerCheckboxes==='function')syncCustomLayerCheckboxes();}catch(e){}
      try{if(typeof syncRouteModeCheckboxes==='function')syncRouteModeCheckboxes();}catch(e){}
      try{if(typeof syncArrowVisibility==='function')syncArrowVisibility();}catch(e){}
      try{if(typeof updateSharedStartPanel==='function')updateSharedStartPanel();}catch(e){}
      return true;
    }finally{
      cell5RestoringViewState=false;
    }
  }

  try{mapObj.on('moveend zoomend overlayadd overlayremove baselayerchange',cell5ScheduleSaveViewState);}catch(e){}
  try{window.addEventListener('pagehide',cell5SaveViewState,{capture:true});}catch(e){}
  try{window.addEventListener('beforeunload',cell5SaveViewState,{capture:true});}catch(e){}

  function cell5RestoreRetry(){
    try{cell5RestoreViewState();}catch(e){}
  }
  // 最後的 runtime 之後再重試數次，兼容桌面與手機直開版的初始化時序。
  setTimeout(cell5RestoreRetry,0);
  setTimeout(cell5RestoreRetry,120);
  setTimeout(cell5RestoreRetry,500);

  function syncCell5FullscreenUi(){
    try{
      const panel=document.getElementById("cell5-custom-layer-panel");
      const inspect=document.getElementById("cell5-inspection-panel");
      const mapEl=mapObj&&mapObj.getContainer?mapObj.getContainer():null;
      if(!mapEl)return;
      const fs=document.fullscreenElement||document.webkitFullscreenElement||document.mozFullScreenElement||document.msFullscreenElement;
      const isMapFullscreen=(fs===mapEl);
      const moveKeep=function(el,parent){
        if(!el||!parent||el.parentElement===parent)return;
        const r=el.getBoundingClientRect();
        parent.appendChild(el);
        const pr=parent.getBoundingClientRect();
        const w=el.offsetWidth,h=el.offsetHeight;
        const maxLeft=Math.max(4,pr.width-w-4),maxTop=Math.max(4,pr.height-h-4);
        el.style.left=Math.max(4,Math.min(r.left-pr.left,maxLeft))+"px";
        el.style.top=Math.max(4,Math.min(r.top-pr.top,maxTop))+"px";
        el.style.right="auto";el.style.bottom="auto";el.style.transform="none";el.style.margin="0";
      };
      if(isMapFullscreen){
        moveKeep(panel,mapEl);moveKeep(inspect,mapEl);
        if(panel)panel.style.zIndex="2147483646";
        if(inspect)inspect.style.zIndex="2147483645";
      }else if(window.innerWidth<=700){
        moveKeep(panel,document.body);moveKeep(inspect,document.body);
        if(panel)panel.style.zIndex="";if(inspect)inspect.style.zIndex="";
      }
      try{mapObj.invalidateSize(false);}catch(e){}
    }catch(e){}
  }
  document.addEventListener("fullscreenchange",syncCell5FullscreenUi);
  document.addEventListener("webkitfullscreenchange",syncCell5FullscreenUi);
  setTimeout(syncCell5FullscreenUi,120);

  function getLayer(v){ try { return v ? window[v] : null; } catch(e){ return null; } }
  function getMarker(v){ try { return v ? window[v] : null; } catch(e){ return null; } }
  function esc(s){
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  }
  function extractName(html){
    const m=String(html||'').match(/<div class="cell5-inspection-name">([\s\S]*?)<\/div>/i);
    if(!m)return '';
    const box=document.createElement('div'); box.innerHTML=m[1];
    return box.textContent || box.innerText || '';
  }
  function extractLatLon(html){
    const s=String(html||'');
    let m=s.match(/maps\/search\/\?api=1&query=([-0-9.]+),([-0-9.]+)/i);
    if(!m)m=s.match(/query=([-0-9.]+),([-0-9.]+)/i);
    if(!m)return null;
    const lat=Number(m[1]), lon=Number(m[2]);
    return Number.isFinite(lat)&&Number.isFinite(lon)?{lat,lon}:null;
  }
  function metaFor(v){
    const raw=inspectionMeta[v]||{};
    const rec=inspectionRecords[v]||'';
    const ll=extractLatLon(rec);
    return {
      lat:Number.isFinite(Number(raw.lat))?Number(raw.lat):(ll?ll.lat:NaN),
      lon:Number.isFinite(Number(raw.lon))?Number(raw.lon):(ll?ll.lon:NaN),
      name:String(raw.display_name||extractName(rec)||''),
      label:String(raw.label||''),
      point_index:raw.point_index,
      return_start_url:String(raw.return_start_url||'')
    };
  }

  // ============================================================
  // 固定起點面板：這一段位於獨立的最終 Runtime IIFE，
  // 因此不能呼叫前一個 IIFE 內部的 showStartInspectionPanel()。
  // 這裡直接建立自己的面板內容，避免作用域問題。
  // ============================================================
  function openStartPanel(){
    try{
      const panel=document.getElementById('cell5-inspection-panel');
      const body=document.getElementById('cell5-inspection-body');
      const title=document.getElementById('cell5-inspection-title');
      if(!panel||!body||!title)return false;

      let targets=[];
      let numberModeActive=false;
      try{
        const numberItem=(layerItems||[]).find(function(x){ return String(x&&x.group||'')==='number'; });
        if(numberItem && numberItem.var){
          const numberLayer=getLayer(numberItem.var);
          numberModeActive=!!(numberLayer && mapObj.hasLayer(numberLayer));
        }
      }catch(_){}

      if(!numberModeActive){
        (dailyDayTargets||[]).forEach(function(t){
          if(t&&t.first_marker_var){
            const layer=t.route_var?getLayer(t.route_var):null;
            if(layer && mapObj.hasLayer(layer)) targets.push(t);
          }
        });
        if(!targets.length && allInOneStartTarget && allInOneStartTarget.first_marker_var){
          const layer=allInOneStartTarget.route_var?getLayer(allInOneStartTarget.route_var):null;
          if(layer && mapObj.hasLayer(layer)) targets.push(allInOneStartTarget);
        }
        // 即使目前沒有勾選任何路線，也維持固定起點可開啟，並提供所有可用入口。
        if(!targets.length){
          (dailyDayTargets||[]).forEach(function(t){ if(t&&t.first_marker_var)targets.push(t); });
          if(!targets.length && allInOneStartTarget && allInOneStartTarget.first_marker_var)targets.push(allInOneStartTarget);
        }
      }

      let html='<b style="font-size:16px;">勘查順序：0｜固定起點</b><br>';
      html+='<div style="margin-top:5px;">所有分日與一次完成共用同一個固定起點。</div>';
      if(numberModeActive){
        html+='<div style="margin-top:10px;color:#666;">目前為「勘查編號」模式，固定起點僅供定位，不提供下一點選擇。</div>';
      }else if(targets.length){
        html+='<div style="margin-top:10px;font-weight:700;">下一點：</div><div class="cell5-start-day-nav">';
        targets.forEach(function(t){
          const v=String(t.first_marker_var||'');
          const label=String(t.label||t.day||'下一點');
          if(v) html+='<button type="button" class="cell5-nav-button" data-cell5-nav-marker="'+esc(v)+'">'+esc(label)+'</button>';
        });
        html+='</div>';
      }else{
        html+='<div style="margin-top:10px;color:#666;">目前沒有可用路線。</div>';
      }
      body.innerHTML=html;
      title.textContent='固定起點｜0';
      panel.classList.add('visible');
      panel.setAttribute('aria-hidden','false');
      return true;
    }catch(e){
      try{console.warn('Cell5 固定起點面板開啟失敗：',e);}catch(_){}
      return false;
    }
  }

  // 事件委派：直接從 DOM 找到「0」圖示，不依賴 Leaflet Marker click。
  // 因此 DAY／一次完成／未勾選時都使用同一套入口，圖層重新建立也不會失效。
  function bindStartDomClick(){
    if(document.__cell5SharedStartDomClickBound)return;
    document.__cell5SharedStartDomClickBound=true;
    document.addEventListener('click',function(e){
      try{
        const t=e.target&&e.target.closest?e.target.closest('.cell5-shared-start-marker'):null;
        if(!t)return;
        e.preventDefault();
        e.stopPropagation();
        if(e.stopImmediatePropagation)e.stopImmediatePropagation();
        openStartPanel();
        try{
          if(Number.isFinite(startLat)&&Number.isFinite(startLon)){
            mapObj.setView([startLat,startLon],Math.max(mapObj.getZoom(),16),{animate:true});
          }
        }catch(_){}
      }catch(err){
        try{console.warn('Cell5 固定起點 DOM 點擊處理失敗：',err);}catch(_){}
      }
    },true);
  }
  bindStartDomClick();

  // ============================================================
  // A. 勘查編號圖層：獨立綁定，並提高 marker 層級避免被 DAY 點蓋住
  // ============================================================
  function promoteNumberMarkers(layer){
    try{
      if(!layer || typeof layer.eachLayer!=='function')return;
      let n=0;
      layer.eachLayer(function(m){ if(m && m.setZIndexOffset)m.setZIndexOffset(50000000-n++); });
    }catch(e){}
  }
  function syncLayerChecks(){
    const body=document.getElementById('cell5-custom-layer-body');
    if(!body)return;
    body.querySelectorAll('.cell5-layer-row').forEach(function(row){
      const input=row.querySelector('input');
      const layer=getLayer(row.getAttribute('data-layer-var')||'');
      if(input&&layer)input.checked=mapObj.hasLayer(layer);
    });
  }
  function bindLayerControls(){
    const body=document.getElementById('cell5-custom-layer-body');
    if(!body)return false;
    body.querySelectorAll('.cell5-layer-row').forEach(function(row){
      const input=row.querySelector('input');
      if(!input || input.dataset.cell5FinalBound==='1')return;
      input.dataset.cell5FinalBound='1';
      input.addEventListener('change',function(e){
        e.stopPropagation();
        const v=row.getAttribute('data-layer-var')||'';
        const type=row.getAttribute('data-layer-type')||'overlay';
        const group=row.getAttribute('data-layer-group')||'';
        const layer=getLayer(v);
        if(!layer)return;
        if(type==='base'){
          if(input.checked){
            layerItems.filter(x=>x.type==='base').forEach(function(item){
              if(item.var===v)return;
              const other=getLayer(item.var);
              if(other&&mapObj.hasLayer(other))mapObj.removeLayer(other);
            });
            mapObj.addLayer(layer);
          }
        }else if(input.checked){
          if(group==='all'){
            layerItems.filter(x=>x.group==='daily'||x.group==='number').forEach(function(item){
              const other=getLayer(item.var);
              if(other&&mapObj.hasLayer(other))mapObj.removeLayer(other);
            });
          }else if(group==='daily'){
            layerItems.filter(x=>x.group==='all'||x.group==='number').forEach(function(item){
              const other=getLayer(item.var);
              if(other&&mapObj.hasLayer(other))mapObj.removeLayer(other);
            });
          }else if(group==='number'){
            layerItems.filter(x=>x.group==='all'||x.group==='daily').forEach(function(item){
              const other=getLayer(item.var);
              if(other&&mapObj.hasLayer(other))mapObj.removeLayer(other);
            });
          }
          mapObj.addLayer(layer);
          if(String(layer.options&&layer.options.name||'')==='勘查編號')promoteNumberMarkers(layer);
        }else if(mapObj.hasLayer(layer)){
          mapObj.removeLayer(layer);
        }
        syncLayerChecks();
      },true);
    });
    syncLayerChecks();
    return true;
  }

  // ============================================================
  // B. 固定起點 0：一定有可點擊 Popup，且直接提供下一點入口
  // ============================================================
  function navButton(v,label){
    return v ? '<button type="button" class="cell5-nav-button cell5-final-nav-button" data-cell5-nav-marker="'+esc(v)+'">'+esc(label)+'</button>' : '';
  }
  function startPopupHtml(){
    let buttons='';
    let numberModeActive=false;
    try{
      const numberItem=(layerItems||[]).find(function(x){ return String(x&&x.group||'')==='number'; });
      if(numberItem && numberItem.var){
        const numberLayer=getLayer(numberItem.var);
        numberModeActive=!!(numberLayer && mapObj.hasLayer(numberLayer));
      }
    }catch(_){}
    if(numberModeActive){
      return '<div class="cell5-start-popup"><div style="font-size:16px;font-weight:700;margin-bottom:5px;">固定起點：0</div><div style="font-size:14px;font-weight:700;">'+esc(startDisplayName)+'</div></div>';
    }
    dailyDayTargets.forEach(function(t){
      if(t&&t.first_marker_var)buttons+=navButton(String(t.first_marker_var),String(t.day||'')+' → 1');
    });
    if(allInOneStartTarget&&allInOneStartTarget.first_marker_var)
      buttons+=navButton(String(allInOneStartTarget.first_marker_var),'一次完成 → 1');
    let h='<div class="cell5-start-popup">';
    h+='<div style="font-size:16px;font-weight:700;margin-bottom:5px;">固定起點：0</div>';
    h+='<div style="font-size:14px;font-weight:700;">'+esc(startDisplayName)+'</div>';
    if(buttons)h+='<div style="margin-top:9px;font-weight:700;">下一點</div><div class="cell5-start-day-nav">'+buttons+'</div>';
    h+='</div>';
    return h;
  }
  function bindStartMarker(){
    const m=getMarker(sharedStartMarkerVar);
    if(!m)return false;
    try{
      m.bindPopup(startPopupHtml(),{maxWidth:420});
      if(!m.__cell5FinalClickBound){
        m.__cell5FinalClickBound=true;
        m.on('click',function(){try{m.openPopup();}catch(e){}});
      }
      return true;
    }catch(e){return false;}
  }

  // ============================================================
  // C. 上一點／下一點：完全以 HTML data-cell5-nav-marker 為索引
  // ============================================================
  const oldNavigate=window.cell5NavigateInspection;
  function fallbackPanel(v){
    const panel=document.getElementById('cell5-inspection-panel');
    const body=document.getElementById('cell5-inspection-body');
    const title=document.getElementById('cell5-inspection-title');
    if(!panel||!body||!title)return;
    const meta=metaFor(v);
    let html=String(inspectionRecords[v]||'');
    title.textContent=meta.label||'勘查點資料';
    body.innerHTML=html||'<div>此點沒有可顯示資料。</div>';
    try{ body.querySelectorAll('.cell5-return-start').forEach(function(el){el.remove();}); }catch(e){}
    try{ if(mapObj.closePopup) mapObj.closePopup(); }catch(e){}
    panel.classList.add('visible');
    panel.setAttribute('aria-hidden','false');
  }
  function centerInspectionTarget(v, animate){
    try{
      const meta=metaFor(v);
      if(!Number.isFinite(meta.lat)||!Number.isFinite(meta.lon)) return false;
      // 避免連按上一點／下一點時，舊動畫把地圖中心拉回去。
      try{ if(mapObj.stop) mapObj.stop(); }catch(e){}
      const zoom=Math.max(mapObj.getZoom(),16);
      mapObj.setView([meta.lat,meta.lon],zoom,{animate:!!animate});
      return true;
    }catch(e){ return false; }
  }
  function closeAndSuspendStartPopup(){
    try{ if(mapObj && mapObj.closePopup) mapObj.closePopup(); }catch(e){}
    try{
      const sm=getMarker(sharedStartMarkerVar);
      if(sm){
        const p=sm.getPopup ? sm.getPopup() : null;
        try{ if(sm.closePopup) sm.closePopup(); }catch(e){}
        try{ if(p && mapObj && mapObj.removeLayer) mapObj.removeLayer(p); }catch(e){}
        try{ if(p && p.remove) p.remove(); }catch(e){}
        try{ if(sm.unbindPopup) sm.unbindPopup(); }catch(e){}
      }
    }catch(e){}
  }
  function restoreStartPopupLater(delay){
    setTimeout(function(){
      try{ bindStartMarker(); }catch(e){}
      try{ ensureStartMarkerInteractive(); }catch(e){}
    }, Number.isFinite(Number(delay)) ? Number(delay) : 650);
  }
  function robustNavigate(v){
    v=String(v||'');
    if(!v)return false;

    function hardCloseTargetPopups(){
      try{ if(mapObj && mapObj.closePopup) mapObj.closePopup(); }catch(e){}
      try{ const sm=getMarker(sharedStartMarkerVar); if(sm&&sm.closePopup)sm.closePopup(); }catch(e){}
      try{ const tm=getMarker(v); if(tm&&tm.closePopup)tm.closePopup(); }catch(e){}
    }

    if(v!==sharedStartMarkerVar){
      closeAndSuspendStartPopup();
    }else{
      hardCloseTargetPopups();
    }

    if(v===sharedStartMarkerVar){
      try{
        bindStartMarker();
        const sm=getMarker(v);
        if(sm&&sm.closePopup)sm.closePopup();
        if(Number.isFinite(startLat)&&Number.isFinite(startLon)){
          try{if(mapObj.stop)mapObj.stop();}catch(e){}
          mapObj.setView([startLat,startLon],Math.max(mapObj.getZoom(),16),{animate:true});
        }
        openStartPanel();
      }catch(e){}
      restoreStartPopupLater(500);
      return false;
    }

    let navigated=false;
    try{
      if(typeof oldNavigate==='function'){
        oldNavigate(v);
        navigated=true;
      }
    }catch(e){}

    if(!navigated){
      try{ fallbackPanel(v); }catch(e){}
    }

    hardCloseTargetPopups();
    try{ centerInspectionTarget(v,true); }catch(e){}
    hardCloseTargetPopups();

    setTimeout(function(){
      try{
        if(mapObj && mapObj.stop)mapObj.stop();
        hardCloseTargetPopups();
        const m=getMarker(v);
        if(m&&m.closePopup)m.closePopup();
        closeAndSuspendStartPopup();
      }catch(e){}
      try{ centerInspectionTarget(v,false); }catch(e){}
      try{ hardCloseTargetPopups(); }catch(e){}
      try{ closeAndSuspendStartPopup(); }catch(e){}
    },80);
    // v34.1：上一點／下一點導航只保留下方「勘查點資訊」面板。
    // 不再重新開啟目標 Marker 的 Leaflet Popup，避免同時出現上下兩個 popup。
    setTimeout(function(){
      try{ hardCloseTargetPopups(); }catch(e){}
      try{ closeAndSuspendStartPopup(); }catch(e){}
      try{ centerInspectionTarget(v,false); }catch(e){}
      try{ hardCloseTargetPopups(); }catch(e){}
    },420);
    setTimeout(function(){
      try{ hardCloseTargetPopups(); }catch(e){}
    },700);
    restoreStartPopupLater(900);

    return false;
  }
